"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[19989],{67727:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>r,contentTitle:()=>s,default:()=>c,frontMatter:()=>i,metadata:()=>a,toc:()=>d});var o=h(31085),n=h(71184);const i={sidebar_position:3,slug:"/bible/2_Machabees/2_Machabees_3",title:"2 Machabees 3",hide_table_of_contents:!0},s="2 Machabees",a={id:"bible/2 Machabees/2 Machabees 3",title:"2 Machabees 3",description:"Chapter 3",source:"@site/docs/bible/2 Machabees/2 Machabees 3.md",sourceDirName:"bible/2 Machabees",slug:"/bible/2_Machabees/2_Machabees_3",permalink:"/docs/bible/2_Machabees/2_Machabees_3",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/2 Machabees/2 Machabees 3.md",tags:[],version:"current",sidebarPosition:3,frontMatter:{sidebar_position:3,slug:"/bible/2_Machabees/2_Machabees_3",title:"2 Machabees 3",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"2 Machabees 2",permalink:"/docs/bible/2_Machabees/2_Machabees_2"},next:{title:"2 Machabees 4",permalink:"/docs/bible/2_Machabees/2_Machabees_4"}},r={},d=[{value:"Chapter 3",id:"chapter-3",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,n.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h1,{id:"2-machabees",children:"2 Machabees"}),"\n",(0,o.jsx)(t.h2,{id:"chapter-3",children:"Chapter 3"}),"\n",(0,o.jsx)(t.p,{children:"Heliodorus is sent by king Seleucus to take away the treasures deposited in the temple.  He is struck by God, and healed by the prayers of the high priest."}),"\n",(0,o.jsx)(h,{verse:1,children:"Therefore, when the holy city was inhabited with all peace, and the laws as yet were very well kept, because of the godliness of Onias, the high priest and the hatred his soul had of evil,"}),"\n",(0,o.jsx)(h,{verse:2,children:"It came to pass that even the kings themselves and the princes esteemed the place worthy of the highest honour, and glorified the temple with very great gifts:"}),"\n",(0,o.jsx)(h,{verse:3,children:"So that Seleucus, king of Asia, allowed out of his revenues all the charges belonging to the ministry of the sacrifices."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Seleucus...Son of Antiochus the Great, and elder brother of Antiochus Epiphanes."})}),"\n",(0,o.jsx)(h,{verse:4,children:"But one Simon, of the tribe of Benjamin, who was appointed overseer of the temple, strove in opposition to the high priest, to bring about some unjust thing in the city."}),"\n",(0,o.jsx)(h,{verse:5,children:"And when he could not overcome Onias, he went to Apollonius, the son of Tharseas, who at that time was governor of Celesyria, and Phenicia:"}),"\n",(0,o.jsx)(h,{verse:6,children:"And told him, that the treasury in Jerusalem was full of immense sums of money, and the common store was infinite, which did not belong to the account of the sacrifices: and that it was possible to bring all into the king's hands."}),"\n",(0,o.jsx)(h,{verse:7,children:"Now when Apollonius had given the king notice concerning the money that he was told of, he called for Heliodorus, who had the charge over his affairs, and sent him with commission to bring him the foresaid money."}),"\n",(0,o.jsx)(h,{verse:8,children:"So Heliodorus forthwith began his journey, under a colour of visiting the cities of Celesyria and Phenicia, but indeed to fulfil the king's purpose."}),"\n",(0,o.jsx)(h,{verse:9,children:"And when he was come to Jerusalem, and had been courteously received in the city by the high priest, he told him what information had been given concerning the money: and declared the cause for which he was come: and asked if these things were so indeed."}),"\n",(0,o.jsx)(h,{verse:10,children:"Then the high priest told him that these were sums deposited, and provisions for the subsistence of the widows and the fatherless:"}),"\n",(0,o.jsx)(h,{verse:11,children:"And that some part of that which wicked Simon had given intelligence of belonged to Hircanus, son of Tobias, a man of great dignity; and that the whole was four hundred talents of silver, and two hundred of gold."}),"\n",(0,o.jsx)(h,{verse:12,children:"But that to deceive them who had trusted to the place and temple which is honoured throughout the whole world, for the reverence and holiness of it, was a thing which could not by any means be done."}),"\n",(0,o.jsx)(h,{verse:13,children:"But he, by reason of the orders he had received from the king, said, that by all means the money must be carried to the king."}),"\n",(0,o.jsx)(h,{verse:14,children:"So on the day he had appointed, Heliodorus entered in to order this matter. But there was no small terror throughout the whole city."}),"\n",(0,o.jsx)(h,{verse:15,children:"And the priests prostrated themselves before the altar in their priests' vestments, and called upon him from heaven, who made the law concerning things given to be kept, that he would preserve them safe, for them that had deposited them."}),"\n",(0,o.jsx)(h,{verse:16,children:"Now whosoever saw the countenance of the high priest, was wounded in heart: for his face, and the changing of his colour, declared the inward sorrow of his mind."}),"\n",(0,o.jsx)(h,{verse:17,children:"For the man was so compassed with sadness and horror of the body, that it was manifest to them that beheld him, what sorrow he had in his heart."}),"\n",(0,o.jsx)(h,{verse:18,children:"Others also came flocking together out of their houses, praying and making public supplication, because the place was like to come into contempt."}),"\n",(0,o.jsx)(h,{verse:19,children:"And the women, girded with haircloth about their breasts, came together in the streets. And the virgins also that were shut up, came forth, some to Onias, and some to the walls, and others looked out of the windows."}),"\n",(0,o.jsx)(h,{verse:20,children:"And all holding up their hands towards heaven made supplication."}),"\n",(0,o.jsx)(h,{verse:21,children:"For the expectation of the mixed multitude, and of the high priest, who was in an agony, would have moved any one to pity."}),"\n",(0,o.jsx)(h,{verse:22,children:"And these indeed called upon almighty God, to preserve the things that had been committed to them safe and sure for those that had committed them."}),"\n",(0,o.jsx)(h,{verse:23,children:"But Heliodorus executed that which he had resolved on, himself being present in the same place with his guard about the treasury."}),"\n",(0,o.jsx)(h,{verse:24,children:"But the spirit of the Almighty God gave a great evidence of his presence, so that all that had presumed to obey him, falling down by the power of God, were struck with fainting and dread."}),"\n",(0,o.jsx)(h,{verse:25,children:"For there appeared to them a horse, with a terrible rider upon him, adorned with a very rich covering: and he ran fiercely and struck Heliodorus with his fore feet, and he that sat upon him seemed to have armour of gold."}),"\n",(0,o.jsx)(h,{verse:26,children:"Moreover there appeared two other young men, beautiful and strong, bright and glorious, and in comely apparel: who stood by him, on either side, and scourged him without ceasing with many stripes."}),"\n",(0,o.jsx)(h,{verse:27,children:"And Heliodorus suddenly fell to the ground, and they took him up, covered with great darkness, and having put him into a litter, they carried him out."}),"\n",(0,o.jsx)(h,{verse:28,children:"So he that came with many servants, and all his guard, into the aforesaid treasury, was carried out, no one being able to help him, the manifest power of God being known."}),"\n",(0,o.jsx)(h,{verse:29,children:"And he indeed, by the power of God, lay speechless, and without all hope of recovery."}),"\n",(0,o.jsx)(h,{verse:30,children:"But they praised the Lord, because he had glorified his place: and the temple, that a little before was full of fear and trouble, when the Almighty Lord appeared, was filled with joy and gladness."}),"\n",(0,o.jsx)(h,{verse:31,children:"Then some of the friends of Heliodorus forthwith begged of Onias, that he would call upon the Most High to grant him his life, who was ready to give up the ghost."}),"\n",(0,o.jsx)(h,{verse:32,children:"So the high priest, considering that the king might perhaps suspect that some mischief had been done to Heliodorus by the Jews, offered a sacrifice of health for the recovery of the man."}),"\n",(0,o.jsx)(h,{verse:33,children:"And when the high priest was praying, the same young men in the same clothing stood by Heliodorus, and said to him: Give thanks to Onias the priest: because for his sake the Lord hath granted thee life."}),"\n",(0,o.jsx)(h,{verse:34,children:"And thou having been scourged by God, declare unto all men the great works and the power of God. And having spoken thus, they appeared no more."}),"\n",(0,o.jsx)(h,{verse:35,children:"So Heliodorus, after he had offered a sacrifice to God, and made great vows to him, that had granted him life, and given thanks to Onias, taking his troops with him, returned to the king."}),"\n",(0,o.jsx)(h,{verse:36,children:"And he testified to all men the works of the great God, which he had seen with his own eyes."}),"\n",(0,o.jsx)(h,{verse:37,children:"And when the king asked Heliodorus, who might be a fit man to be sent yet once more to Jerusalem, he said:"}),"\n",(0,o.jsx)(h,{verse:38,children:"If thou hast any enemy, or traitor to thy king dom, send him thither, and thou shalt receive him again scourged, if so be he escape: for there is undoubtedly in that place a certain power of God."}),"\n",(0,o.jsx)(h,{verse:39,children:"For he that hath his dwelling in the heavens, is the visitor and protector of that place, and he striketh and destroyeth them that come to do evil to it."}),"\n",(0,o.jsx)(h,{verse:40,children:"And the things concerning Heliodorus, and the keeping of the treasury, fell out in this manner."})]})}function c(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>s,x:()=>a});var o=h(14041);const n={},i=o.createContext(n);function s(e){const t=o.useContext(i);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);